import * as fs from 'node:fs';
import * as path from 'node:path';
import { writeFileIfChanged } from './files';

/**
 * The project's CMakeUserPresets.json, which includes each profile's Conan-generated
 * CMakePresets.json. Written once after all installs rather than by Conan after each one.
 */
export function userPresetsPath(projectDirectory: string): string {
  return path.join(projectDirectory, 'CMakeUserPresets.json');
}

/**
 * True if the file is missing or was generated by Conan/this extension. A hand-written file is
 * never overwritten (Conan follows the same rule).
 */
export function canWriteUserPresets(projectDirectory: string): boolean {
  const filePath = userPresetsPath(projectDirectory);
  if (!fs.existsSync(filePath)) {
    return true;
  }

  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'))?.vendor?.conan !== undefined;
  } catch {
    return false;
  }
}

/** Paths of the included presets files, resolved against the project directory. */
export function readUserPresetsIncludes(projectDirectory: string): string[] {
  const filePath = userPresetsPath(projectDirectory);
  if (!fs.existsSync(filePath)) {
    return [];
  }

  const include: unknown = JSON.parse(fs.readFileSync(filePath, 'utf8'))?.include;
  return Array.isArray(include)
    ? include.filter((item): item is string => typeof item === 'string').map(item => path.resolve(projectDirectory, item))
    : [];
}

/**
 * Writes the file so it includes exactly `presetsFiles`.
 * @returns true if the file changed.
 */
export function writeUserPresets(projectDirectory: string, presetsFiles: readonly string[]): boolean {
  const document = {
    version: 4,
    // The "conan" vendor key keeps Conan treating the file as generated, so a manual
    // 'conan install' may still update it.
    vendor: { conan: {} },
    include: presetsFiles.map(file => toIncludePath(projectDirectory, file)),
  };

  return writeFileIfChanged(userPresetsPath(projectDirectory), JSON.stringify(document, null, 4) + '\n');
}

/** Names of the configure presets in a Conan-generated CMakePresets.json. */
export function readConfigurePresetNames(presetsFile: string): string[] {
  try {
    const presets: unknown = JSON.parse(fs.readFileSync(presetsFile, 'utf8'))?.configurePresets;
    return Array.isArray(presets)
      ? presets.map(preset => preset?.name).filter((name): name is string => typeof name === 'string')
      : [];
  } catch {
    return [];
  }
}

function toIncludePath(projectDirectory: string, file: string): string {
  const relative = path.relative(projectDirectory, file);
  const inside = relative !== '' && !relative.startsWith('..') && !path.isAbsolute(relative);
  return (inside ? relative : path.resolve(file)).split(path.sep).join('/');
}
